<?php
declare(strict_types=1);
namespace App\Modules\CommercialRental\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use RuntimeException;use Throwable;
use App\Modules\CommercialRental\Services\CommercialRentalRequestService;use App\Modules\CommercialRental\Services\CommercialRentalProviderService;use App\Modules\CommercialRental\Services\CommercialRentalVehicleService;
final class CommercialRentalRequestController extends Controller{private CommercialRentalRequestService$s;private CommercialRentalProviderService$p;private CommercialRentalVehicleService$v;private Authorization$a;public function __construct(){$this->s=new CommercialRentalRequestService();$this->p=new CommercialRentalProviderService();$this->v=new CommercialRentalVehicleService();$this->a=new Authorization();}private function ok(string$p,string$r='/commercial-rentals/requests'):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException$e){flash('error',$e->getMessage());redirect($r);return false;}}private function data(int$t,array$x=[]):array{return['providers'=>$this->p->all($t),'vehicles'=>$this->v->all($t)]+$x;}public function index():void{if(!$this->ok('commercial_rental.requests.view'))return;$this->view('CommercialRental::Requests.index',['title'=>'Rental Requests','requests'=>$this->s->all((int)Auth::tenantId())]);}public function create():void{if(!$this->ok('commercial_rental.requests.create'))return;$this->view('CommercialRental::Requests.create',$this->data((int)Auth::tenantId(),['title'=>'Create Rental Request']));}public function store():void{if(!$this->ok('commercial_rental.requests.create'))return;try{$this->s->create((int)Auth::tenantId(),$_POST,(int)Auth::id());flash('success','Rental request created.');redirect('/commercial-rentals/requests');}catch(Throwable$e){$this->view('CommercialRental::Requests.create',$this->data((int)Auth::tenantId(),['title'=>'Create Rental Request','error'=>$e->getMessage(),'old'=>$_POST]));}}public function show(int$id):void{if(!$this->ok('commercial_rental.requests.view'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('CommercialRental::Requests.show',['title'=>$r['request_no'],'record'=>$r]);}public function edit(int$id):void{if(!$this->ok('commercial_rental.requests.edit'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('CommercialRental::Requests.edit',$this->data((int)Auth::tenantId(),['title'=>'Edit Rental Request','record'=>$r]));}public function update(int$id):void{if(!$this->ok('commercial_rental.requests.edit'))return;try{$this->s->update((int)Auth::tenantId(),$id,$_POST,(int)Auth::id());flash('success','Request updated.');redirect('/commercial-rentals/requests/'.$id);}catch(Throwable$e){$this->view('CommercialRental::Requests.edit',$this->data((int)Auth::tenantId(),['title'=>'Edit Rental Request','record'=>$_POST,'error'=>$e->getMessage()]));}}public function updateStatus(int$id):void{if(!$this->ok('commercial_rental.requests.manage'))return;try{$this->s->status((int)Auth::tenantId(),$id,(string)($_POST['status']??''),(int)Auth::id());flash('success','Request status updated.');}catch(Throwable$e){flash('error',$e->getMessage());}redirect('/commercial-rentals/requests/'.$id);}public function destroy(int$id):void{if(!$this->ok('commercial_rental.requests.delete'))return;$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Request deleted.');redirect('/commercial-rentals/requests');}}
